        vector<TreeNode*> qPath = pathTo(root, q);

        TreeNode* answer = root;

        for (int i = 0; i < (int)min(pPath.size(), qPath.size()); i++) {
            if (pPath[i] != qPath[i]) break;
            answer = pPath[i];
        }

        return answer;
